1	import type { Metadata } from "next";
2	import Link from "next/link";
3	import { PageHero, Section, SectionTitle } from "@/components/marketing/primitives";
4	import { StoreBrowser, type SortKey } from "@/components/mods/StoreBrowser";
5	import { PopularGamesStrip } from "@/components/mods/PopularGamesStrip";
6	import { FaqJsonLd } from "@/components/marketing/StructuredData";
7	import { listCatalogFamilies, queryCatalogMods, totalDownloadsFor, formatDownloads } from "@/lib/mods-catalog";
8	
9	export const dynamic = "force-dynamic";
10	
11	const VALID_SORTS = new Set<SortKey>(["featured", "downloads", "latest", "rating"]);
12	function parseSort(v?: string): SortKey {
13	  return v && VALID_SORTS.has(v as SortKey) ? (v as SortKey) : "featured";
14	}
15	
16	export const metadata: Metadata = {
17	  title: "NxLabs — Free Mods, Plugins & Server Add-ons",
18	  description:
19	    "NxLabs is Nxeon's free, public mod & plugin catalog — verified against Modrinth, SpigotMC, and Thunderstore. Browse and download with no account required.",
20	  alternates: { canonical: "/mods" },
21	  openGraph: { title: "NxLabs — Free Mods, Plugins & Server Add-ons", type: "website" },
22	};
23	
24	const FAQ = [
25	  {
26	    q: "Do I need an Nxeon account to download from NxLabs?",
27	    a: "No. Every mod page links to its real, authoritative source (Modrinth, SpigotMC, or Thunderstore) — anyone can download for free with no account.",
28	  },
29	  {
30	    q: "What does \"Verified\" mean on a mod?",
31	    a: "Verified mods have been checked live against their source's own API — real download counts, supported game versions, and file size, refreshed periodically so a removed or deprecated project stops being listed.",
32	  },
33	  {
34	    q: "Can I install a mod straight onto my server?",
35	    a: "If you have an Nxeon game server matching the mod's game, log in and use \"Add to my server\" for a one-click install. Anyone else gets the same direct download link.",
36	  },
37	];
38	
39	type Search = { q?: string; sort?: string; page?: string };
40	
41	export default async function ModsCatalogPage({ searchParams }: { searchParams: Promise<Search> }) {
42	  const sp = await searchParams;
43	  const q = (sp.q ?? "").trim();
44	  const sort = parseSort(sp.sort);
45	  const page = Number(sp.page) || 1;
46	
47	  const [families, result, totalDownloads] = await Promise.all([
48	    listCatalogFamilies(),
49	    queryCatalogMods({ q, sort, page }),
50	    totalDownloadsFor(),
51	  ]);
52	  const { mods, total, totalPages, perPage, page: resolvedPage } = result;
53	  const totalMods = families.reduce((sum, f) => sum + f.count, 0);
54	
55	  // Family chips point at the real dedicated /mods/games/[family] pages
56	  // (already correctly paginated) rather than re-filtering this page's own
57	  // array in place — the counts here are real DB-wide totals
58	  // (listCatalogFamilies' own groupBy), and at 32k+ mods in one family a
59	  // client-side re-filter of just this page's ~24 loaded rows could show
60	  // "0 results" for a chip advertising thousands.
61	  const chips = families.map((f) => ({ key: f.family, label: f.label, count: f.count, href: `/mods/games/${f.family}` }));
62	
63	  return (
64	    <>
65	      <FaqJsonLd items={FAQ} />
66	      <PageHero
67	        logo={
68	          // eslint-disable-next-line @next/next/no-img-element
69	          <img src="/nxlabs/logo.png" alt="NxLabs" className="h-10 w-auto" />
70	        }
71	        eyebrow="Mods fuel better games"
72	        title="Customize without"
73	        highlight="limits"
74	        sub="Discover, download, and share verified mods, plugins, and add-ons for your favorite Nxeon-hosted games — real download counts, real licenses, always a direct link to the source."
75	        primary={{ label: "Browse mods", href: "#browse" }}
76	        secondary={{ label: "Explore games", href: "#games" }}
77	        visual={
78	          // eslint-disable-next-line @next/next/no-img-element
79	          <img
80	            src="/nxlabs/hero-collage.png"
81	            alt="Mods across Minecraft, Rust, Valheim, CS2 and Palworld"
82	            className="w-full rounded-2xl border border-white/10 object-cover"
83	          />
84	        }
85	      />
86	
87	      <Section>
88	        <div className="mx-auto grid max-w-4xl grid-cols-3 gap-4 text-center">
89	          <Stat value={totalMods.toLocaleString()} label="Mods & plugins" />
90	          <Stat value={String(families.length)} label="Games supported" />
91	          <Stat value={formatDownloads(totalDownloads) ?? "0"} label="Total downloads" />
92	        </div>
93	      </Section>
94	
95	      <Section>
96	        <div id="games">
97	          <SectionTitle eyebrow="Browse by game" title="Popular games" />
98	          <div className="mt-6">
99	            <PopularGamesStrip families={families} hrefFor={(family) => `/mods/games/${family}`} />
100	          </div>
101	        </div>
102	      </Section>
103	
104	      <Section>
105	        <div id="browse">
106	          <SectionTitle eyebrow="The full catalog" title="Featured mods" />
107	          <div className="mt-6">
108	            <StoreBrowser
109	              mods={mods}
110	              total={total}
111	              page={resolvedPage}
112	              totalPages={totalPages}
113	              perPage={perPage}
114	              chips={chips}
115	              chipField="gameFamily"
116	              basePath="/mods"
117	              q={q}
118	              sort={sort}
119	              showGameBadge
120	            />
121	          </div>
122	        </div>
123	      </Section>
124	
125	      <Section>
126	        <SectionTitle title="Frequently asked" />
127	        <div className="mx-auto mt-6 max-w-2xl divide-y divide-white/10">
128	          {FAQ.map((f) => (
129	            <div key={f.q} className="py-4">
130	              <h3 className="text-sm font-semibold text-[var(--fg)]">{f.q}</h3>
131	              <p className="mt-1 text-sm text-[var(--fg-muted)]">{f.a}</p>
132	            </div>
133	          ))}
134	        </div>
135	        <p className="mt-8 text-center text-xs text-[var(--fg-muted)]">
136	          Running an Nxeon game server? Install any of these in one click from your{" "}
137	          <Link href="/dashboard/nxlabs" className="text-brand-300 underline underline-offset-2">
138	            dashboard
139	          </Link>
140	          , or read about our built-in{" "}
141	          <Link href="/game-servers/mods" className="text-brand-300 underline underline-offset-2">
142	            Mod Store
143	          </Link>
144	          .
145	        </p>
146	      </Section>
147	    </>
148	  );
149	}
150	
151	function Stat({ value, label }: { value: string; label: string }) {
152	  return (
153	    <div>
154	      <p className="text-2xl font-bold text-[var(--fg)] sm:text-3xl">{value}</p>
155	      <p className="text-xs text-[var(--fg-muted)] sm:text-sm">{label}</p>
156	    </div>
157	  );
158	}
