1	import type { Metadata } from "next";
2	import Link from "next/link";
3	import { notFound } from "next/navigation";
4	import { db } from "@/lib/db";
5	import { currentUser } from "@/lib/auth";
6	import { Section } from "@/components/marketing/primitives";
7	import { ModCard } from "@/components/mods/ModCard";
8	import { AddToServerWidget } from "@/components/mods/AddToServerWidget";
9	import { AuthorBadge } from "@/components/mods/AuthorBadge";
10	import { GalleryStrip } from "@/components/mods/GalleryStrip";
11	import { RatingsAndComments } from "@/components/mods/RatingsAndComments";
12	import { APP_URL } from "@/components/marketing/StructuredData";
13	import {
14	  getCatalogMod,
15	  listCatalogSlugs,
16	  relatedCatalogMods,
17	  recommendedPlanFor,
18	  resolveDownloadUrl,
19	  listModComments,
20	  getMyModRating,
21	  formatDownloads,
22	  formatBytes,
23	  SOURCE_LABEL,
24	} from "@/lib/mods-catalog";
25	
26	export const dynamic = "force-dynamic";
27	
28	type Params = { params: Promise<{ family: string; slug: string }> };
29	
30	export async function generateStaticParams(): Promise<Array<{ family: string; slug: string }>> {
31	  return listCatalogSlugs();
32	}
33	
34	export async function generateMetadata({ params }: Params): Promise<Metadata> {
35	  const { family, slug } = await params;
36	  const mod = await getCatalogMod(family, slug);
37	  if (!mod) return { title: "Mod not found" };
38	  const title = `${mod.name} — ${mod.gameFamilyLabel} ${mod.category} | NxLabs`;
39	  const description =
40	    mod.description ||
41	    `${mod.name} for ${mod.gameFamilyLabel}, verified against ${SOURCE_LABEL[mod.source] ?? mod.source} — real download counts, supported versions, and a direct download link.`;
42	  return {
43	    title,
44	    description,
45	    alternates: { canonical: `/mods/${mod.gameFamily}/${mod.slug}` },
46	    openGraph: {
47	      title,
48	      description,
49	      type: "website",
50	      url: `${APP_URL}/mods/${mod.gameFamily}/${mod.slug}`,
51	      ...(mod.iconUrl ? { images: [mod.iconUrl] } : {}),
52	    },
53	  };
54	}
55	
56	export default async function ModDetailPage({ params }: Params) {
57	  const { family, slug } = await params;
58	  const mod = await getCatalogMod(family, slug);
59	  if (!mod) notFound();
60	
61	  const user = await currentUser();
62	  const [gamePlans, related, download, commentsPage, myRating] = await Promise.all([
63	    db.gamePlan.findMany({ where: { gameFamily: mod.gameFamily, active: true }, orderBy: { priceCents: "asc" } }),
64	    relatedCatalogMods(mod, 4),
65	    resolveDownloadUrl(mod),
66	    listModComments(mod.id, { take: 10 }),
67	    user ? getMyModRating(mod.id, user.id) : Promise.resolve(null),
68	  ]);
69	  const recommended = recommendedPlanFor(mod, gamePlans);
70	  const downloads = formatDownloads(mod.downloads);
71	  const fileSize = formatBytes(mod.fileBytes);
72	  const heroImage = mod.galleryUrls[0] ?? mod.iconUrl ?? null;
73	
74	  return (
75	    <>
76	      {/* SoftwareApplication, not Product — this is a free, third-party-hosted
77	          download, not something Nxeon sells. price: "0" is the accurate,
78	          Google-documented way to mark a free application. aggregateRating is
79	          now real (ModRating), so it's included ONLY when at least one exists
80	          — never a fabricated 0/0. */}
81	      <script
82	        type="application/ld+json"
83	        // eslint-disable-next-line react/no-danger
84	        dangerouslySetInnerHTML={{
85	          __html: JSON.stringify({
86	            "@context": "https://schema.org",
87	            "@type": "SoftwareApplication",
88	            name: mod.name,
89	            applicationCategory: "GameApplication",
90	            operatingSystem: mod.gameFamilyLabel,
91	            description: mod.description || `${mod.name} for ${mod.gameFamilyLabel}.`,
92	            ...(mod.iconUrl ? { image: mod.iconUrl } : {}),
93	            ...(download ? { downloadUrl: download.url } : {}),
94	            offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
95	            ...(mod.avgRating != null
96	              ? {
97	                  aggregateRating: {
98	                    "@type": "AggregateRating",
99	                    ratingValue: mod.avgRating.toFixed(1),
100	                    reviewCount: mod.ratingCount,
101	                  },
102	                }
103	              : {}),
104	          }),
105	        }}
106	      />
107	
108	      <section className="relative overflow-hidden">
109	        {heroImage && (
110	          <div className="absolute inset-0 -z-10">
111	            {/* eslint-disable-next-line @next/next/no-img-element */}
112	            <img src={heroImage} alt="" className="h-full w-full object-cover opacity-25 blur-sm" />
113	            <div className="absolute inset-0 bg-gradient-to-t from-[var(--bg)] via-[var(--bg)]/80 to-[var(--bg)]/40" />
114	          </div>
115	        )}
116	        <div className="rail py-16 sm:py-20">
117	          <p className="text-xs font-semibold uppercase tracking-widest text-brand-300">
118	            <Link href="/mods" className="hover:underline">
119	              NxLabs
120	            </Link>{" "}
121	            /{" "}
122	            <Link href={`/mods/games/${mod.gameFamily}`} className="hover:underline">
123	              {mod.gameFamilyLabel}
124	            </Link>
125	          </p>
126	          <div className="mt-3 flex flex-wrap items-center gap-4">
127	            {mod.iconUrl && (
128	              // eslint-disable-next-line @next/next/no-img-element
129	              <img src={mod.iconUrl} alt="" className="h-16 w-16 rounded-2xl border border-white/10 object-cover" />
130	            )}
131	            <div>
132	              <h1 className="text-3xl font-bold text-[var(--fg)] sm:text-4xl">{mod.name}</h1>
133	              {mod.authorName && (
134	                <div className="mt-1">
135	                  <AuthorBadge name={mod.authorName} avatarUrl={mod.authorAvatarUrl} />
136	                </div>
137	              )}
138	            </div>
139	          </div>
140	          {mod.description && <p className="mt-4 max-w-2xl text-[var(--fg-muted)]">{mod.description}</p>}
141	        </div>
142	      </section>
143	
144	      <Section>
145	        <div className="mx-auto grid max-w-5xl gap-8 lg:grid-cols-[1.4fr_1fr]">
146	          <div className="space-y-6">
147	            {mod.galleryUrls.length > 0 && <GalleryStrip images={mod.galleryUrls} alt={mod.name} />}
148	
149	            <div className="card p-6">
150	              <h2 className="text-lg font-semibold text-[var(--fg)]">Download</h2>
151	              {download ? (
152	                <>
153	                  <a href={download.url} className="btn-primary mt-4 inline-flex" target="_blank" rel="noopener noreferrer nofollow">
154	                    {download.direct ? "Download file" : `View on ${SOURCE_LABEL[mod.source] ?? mod.source}`}
155	                  </a>
156	                </>
157	              ) : (
158	                <p className="mt-3 text-sm text-[var(--fg-muted)]">No download link is available for this entry right now.</p>
159	              )}
160	
161	              <div className="mt-6">
162	                <AddToServerWidget modId={mod.id} gameFamily={mod.gameFamilyLabel} downloadUrl={download?.url ?? null} />
163	              </div>
164	
165	              {!mod.upstreamOk && (
166	                <p className="mt-4 rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
167	                  {mod.upstreamNote || "This mod is no longer supported by its source."}
168	                </p>
169	              )}
170	            </div>
171	
172	            <RatingsAndComments
173	              modId={mod.id}
174	              avgRating={mod.avgRating}
175	              ratingCount={mod.ratingCount}
176	              initialComments={commentsPage.comments}
177	              initialCursor={commentsPage.nextCursor}
178	              myRating={myRating}
179	              isLoggedIn={!!user}
180	              isAdmin={user?.role === "ADMIN"}
181	              loginHref={`/login?next=${encodeURIComponent(`/mods/${mod.gameFamily}/${mod.slug}`)}`}
182	            />
183	          </div>
184	
185	          <aside className="space-y-6">
186	            <div className="card p-6">
187	              <h2 className="text-sm font-semibold uppercase tracking-wide text-[var(--fg-muted)]">Details</h2>
188	              <dl className="mt-4 space-y-3 text-sm">
189	                <Row label="Game">{mod.gameFamilyLabel}</Row>
190	                <Row label="Category">{mod.category}</Row>
191	                <Row label="Source">{SOURCE_LABEL[mod.source] ?? mod.source}</Row>
192	                {mod.license && <Row label="License">{mod.license}</Row>}
193	                {downloads && <Row label="Downloads">{downloads}</Row>}
194	                {fileSize && <Row label="File size">{fileSize}</Row>}
195	                {mod.gameVersions.length > 0 && (
196	                  <Row label="Game versions">{mod.gameVersions.slice(-6).reverse().join(", ")}</Row>
197	                )}
198	                {mod.loaders.length > 0 && <Row label="Loaders">{mod.loaders.join(", ")}</Row>}
199	                {mod.appliesToVariant && <Row label="Requires">{mod.appliesToVariant} server type</Row>}
200	                {mod.serverSide && <Row label="Server support">{mod.serverSide}</Row>}
201	                <Row label="Verified">
202	                  {mod.verified ? `Yes — checked ${mod.verifiedAt?.toISOString().slice(0, 10)}` : "Not yet verified"}
203	                </Row>
204	              </dl>
205	            </div>
206	
207	            <div className="card p-6">
