169	export type CatalogSort = "featured" | "downloads" | "latest" | "rating";
170	
171	export type CatalogPage = {
172	  mods: ModSummary[];
173	  total: number;
174	  page: number;
175	  totalPages: number;
176	  perPage: number;
177	};
178	
179	/**
180	 * Every scalar `orderBy` StoreBrowser's sort tabs can ask for. "rating" is
181	 * the one honest exception: avgRating is computed from a separate ModRating
182	 * table with no cached column on GameMod, and Prisma's relation-aggregate
183	 * `orderBy` only supports `_count` (not `_avg`) for to-many relations — there
184	 * is no cheap DB-side "top rated" ordering to give it. Fetching by downloads
185	 * and re-sorting by rating WITHIN each page (below) is a documented
186	 * approximation: "Top Rated" page 2 shows the 25th-48th most-downloaded mods
187	 * re-ordered by rating, not the true 25th-48th highest-rated mods
188	 * catalogue-wide. That is honest and fine at today's rating volumes (a small
189	 * fraction of 32k+ mods have any reviews at all); if ratings ever justify
190	 * it, add a cached avgRating/ratingCount column on GameMod (maintained by
191	 * the rating mutation) and give this its own real orderBy.
192	 */
193	const ORDER_BY: Record<CatalogSort, Prisma.GameModOrderByWithRelationInput[]> = {
194	  featured: [{ featured: "desc" }, { downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
195	  downloads: [{ downloads: "desc" }, { name: "asc" }],
196	  latest: [{ createdAt: "desc" }],
197	  rating: [{ downloads: "desc" }, { name: "asc" }],
198	};
199	
200	/**
201	 * Real, server-side, paginated + searched + sorted catalogue query — the
202	 * single data source behind every StoreBrowser instance (marketing and
203	 * portal, cross-game and per-family). Replaces the old
204	 * `listCatalogMods`/`searchCatalogMods` pair, which fetched (at most)
205	 * `CATALOG_LIST_CAP` rows once and left every control on top of it running
206	 * over that fixed in-memory array — fine at ~124 hand-seeded rows, silently
207	 * capping the catalogue at families with thousands+ of real imported rows.
208	 */
209	export async function queryCatalogMods(opts: {
210	  family?: string;
211	  /** Category filter — the per-family page's chips (StoreBrowser's `chipField: "category"`). */
212	  category?: string;
213	  q?: string;
214	  sort?: CatalogSort;
215	  page?: number;
216	  perPage?: number;
217	}): Promise<CatalogPage> {
218	  const sort = opts.sort ?? "featured";
219	  const q = (opts.q ?? "").trim();
220	  const where: Prisma.GameModWhereInput = {
221	    active: true,
222	    upstreamOk: true,
223	    ...(opts.family ? { gameFamily: opts.family } : {}),
224	    ...(opts.category ? { category: opts.category } : {}),
225	    ...(q
226	      ? {
227	          OR: [
228	            { name: { contains: q, mode: "insensitive" } },
229	            { category: { contains: q, mode: "insensitive" } },
230	            { description: { contains: q, mode: "insensitive" } },
231	          ],
232	        }
233	      : {}),
234	  };
235	
236	  const total = await db.gameMod.count({ where });
237	  const { skip, take, page, pages, perPage } = paginate(
238	    { page: opts.page != null ? String(opts.page) : undefined },
239	    total,
240	    opts.perPage ?? CATALOG_PAGE_SIZE
241	  );
242	
243	  const rows = await db.gameMod.findMany({ where, orderBy: ORDER_BY[sort], skip, take });
244	  const aggs = await ratingAggs(rows.map((r) => r.id));
245	  const mods = rows.map((r) => toSummary(r, aggs.get(r.id)));
246	  if (sort === "rating") {
247	    mods.sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount);
248	  }
249	
250	  return { mods, total, page, totalPages: pages, perPage };
251	}
