290	export async function relatedCatalogMods(mod: ModDetail, take = 4): Promise<ModSummary[]> {
291	  const rows = await db.gameMod.findMany({
292	    where: { active: true, upstreamOk: true, gameFamily: mod.gameFamily, id: { not: mod.id } },
293	    orderBy: [{ downloads: "desc" }, { popularity: "desc" }],
294	    take: take * 3, // over-fetch a little so the same-category re-sort below has real options
295	  });
296	  const aggs = await ratingAggs(rows.map((r) => r.id));
297	  // Prefer same-category matches first, client-side sort (small result set).
298	  return rows
299	    .map((r) => toSummary(r, aggs.get(r.id)))
300	    .sort((a, b) => Number(b.category === mod.category) - Number(a.category === mod.category))
301	    .slice(0, take);
