/**
 * Refuse to write to a database nobody deliberately pointed us at.
 *
 * ---------------------------------------------------------------------------
 * THE INCIDENT THIS EXISTS FOR (2026-07-26)
 * ---------------------------------------------------------------------------
 * An agent ran `prisma/seed.ts` from a scratch working tree. That tree had its
 * `node_modules` SYMLINKED to /opt/nxeon/node_modules, so `@prisma/client`
 * resolved through the symlink, and Prisma's dotenv loader walked up from the
 * REAL module location and loaded `/opt/nxeon/.env` — the PRODUCTION env. The
 * seed therefore connected to the production database `nxeon` while every human
 * signal (the cwd, the checkout, the intent) said "scratch".
 *
 * It happened to be a pure `upsert` seed, so it did no damage. That is luck, not
 * a control. The same accident with `prisma db push --accept-data-loss`, or with
 * a seed that had grown a `deleteMany`, destroys a live hosting platform's
 * customer records.
 *
 * The root cause is NOT "the seed was careless". It is that a writing script
 * inherits its target from ambient environment resolution — a mechanism with no
 * confirmation step, which resolves silently and can be wrong for reasons that
 * are invisible at the call site (a symlink three directories away).
 *
 * ---------------------------------------------------------------------------
 * THE CONTROL
 * ---------------------------------------------------------------------------
 * A writing script must state, out loud, which database it believes it is about
 * to write to. The operator states it independently, via `NXEON_DB_TARGET`. The
 * script runs only if the two agree.
 *
 *     NXEON_DB_TARGET=nxeon_staging npx tsx prisma/seed.ts
 *
 * This is deliberately NOT a "--force"/"--yes" flag. A blanket confirmation
 * answers "do you want to proceed?", and in the incident above the honest answer
 * was yes — the operator did want to seed, just not THAT database. Naming the
 * target answers the question that was actually wrong. An operator who types
 * `NXEON_DB_TARGET=nxeon_scratch` while the environment silently resolves to
 * `nxeon` gets a refusal and a diff, which is exactly the moment the symlink
 * becomes visible.
 *
 * Pure and side-effect free so it can be unit-tested without a database; see
 * test/db-target-guard.test.ts.
 */

/** Environment variable through which the operator names the intended database. */
export const TARGET_ENV_VAR = "NXEON_DB_TARGET";

export type DbTargetDecision =
  | { allowed: true; database: string }
  | { allowed: false; database: string | null; message: string };

/**
 * Extract the database NAME from a PostgreSQL connection URL.
 *
 * Returns null when the URL is absent, unparseable, or names no database. We do
 * not guess: a connection string we cannot read is a connection string we cannot
 * confirm, and the whole point here is to stop acting on unconfirmed targets.
 */
export function databaseNameFromUrl(url: string | undefined | null): string | null {
  if (!url) return null;
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return null;
  }
  if (!/^postgres(ql)?:$/.test(parsed.protocol)) return null;
  // pathname is "/dbname" (or "" / "/" when no database is named).
  const raw = parsed.pathname.replace(/^\//, "");
  if (!raw) return null;
  let name: string;
  try {
    name = decodeURIComponent(raw);
  } catch {
    // A malformed percent-escape means we cannot say what database this is.
    return null;
  }
  return name || null;
}

/**
 * Decide whether a writing script may proceed.
 *
 * `declared` is what the operator said (NXEON_DB_TARGET); `databaseUrl` is what
 * the environment silently resolved to. They must agree.
 */
export function decideDbTarget(opts: {
  databaseUrl: string | undefined | null;
  declared: string | undefined | null;
  /** Script name, used only to make the refusal message copy-pasteable. */
  script: string;
}): DbTargetDecision {
  const { databaseUrl, declared, script } = opts;
  const resolved = databaseNameFromUrl(databaseUrl);

  if (!databaseUrl) {
    return {
      allowed: false,
      database: null,
      message:
        `Refusing to run ${script}: DATABASE_URL is not set.\n` +
        `Nothing was written. Set DATABASE_URL and ${TARGET_ENV_VAR} to the same database.`,
    };
  }

  if (!resolved) {
    return {
      allowed: false,
      database: null,
      message:
        `Refusing to run ${script}: DATABASE_URL does not name a PostgreSQL database.\n` +
        `Nothing was written. Could not determine a database name from the connection string,\n` +
        `so there is no target to confirm against ${TARGET_ENV_VAR}.`,
    };
  }

  const want = (declared ?? "").trim();
  if (!want) {
    return {
      allowed: false,
      database: resolved,
      message:
        `Refusing to run ${script}: ${TARGET_ENV_VAR} is not set.\n` +
        `Nothing was written.\n\n` +
        `This environment resolves to the database: ${resolved}\n\n` +
        `If that is genuinely the database you meant to write to, say so explicitly:\n` +
        `    ${TARGET_ENV_VAR}=${resolved} <your command>\n\n` +
        `Check it first. DATABASE_URL is resolved from a .env file that dotenv finds by\n` +
        `walking up from the Prisma client's REAL location — which, if node_modules is a\n` +
        `symlink, is not the tree you are standing in.`,
    };
  }

  if (want !== resolved) {
    return {
      allowed: false,
      database: resolved,
      message:
        `Refusing to run ${script}: the database does not match what you asked for.\n` +
        `Nothing was written.\n\n` +
        `  ${TARGET_ENV_VAR} (what you asked for)  : ${want}\n` +
        `  DATABASE_URL    (what it resolved to): ${resolved}\n\n` +
        `These disagree, so one of them is wrong and it is not safe to guess which.\n` +
        `The usual cause is a .env being picked up from a different tree than the one you\n` +
        `are working in (a symlinked node_modules will do it). Confirm with:\n` +
        `    node -e 'console.log(process.env.DATABASE_URL)'`,
    };
  }

  return { allowed: true, database: resolved };
}

/**
 * Enforce the decision, or exit non-zero having written nothing.
 *
 * Exits rather than throwing: a throw from a top-level `main()` that lacks a
 * `.catch` becomes an unhandled rejection, which prints a stack trace and buries
 * the one sentence the operator needs to read.
 */
export function assertDbTarget(script: string): string {
  const decision = decideDbTarget({
    databaseUrl: process.env.DATABASE_URL,
    declared: process.env[TARGET_ENV_VAR],
    script,
  });
  if (!decision.allowed) {
    console.error(`\n${decision.message}\n`);
    process.exit(1);
  }
  console.log(`[${script}] target database confirmed: ${decision.database}`);
  return decision.database;
}

