/**
 * One-off read-only check: how many active GameMod rows have a null/empty
 * `description`, broken down by source. Informs the NxLabs description
 * backfill scope. Read-only — no db-target-guard needed (nothing is written).
 * Delete after use.
 */
import { db } from "../lib/db";

async function main() {
  const rows = await db.gameMod.groupBy({
    by: ["source"],
    where: { active: true, upstreamOk: true },
    _count: true,
  });
  const empty = await db.gameMod.groupBy({
    by: ["source"],
    where: {
      active: true,
      upstreamOk: true,
      OR: [{ description: null }, { description: "" }],
    },
    _count: true,
  });
  const emptyMap = new Map(empty.map((r) => [r.source, r._count]));

  console.log("source            total    empty/null-desc   %");
  let totalAll = 0;
  let emptyAll = 0;
  for (const r of rows.sort((a, b) => b._count - a._count)) {
    const e = emptyMap.get(r.source) ?? 0;
    totalAll += r._count;
    emptyAll += e;
    console.log(
      `${r.source.padEnd(16)} ${String(r._count).padStart(7)}  ${String(e).padStart(14)}   ${((e / r._count) * 100).toFixed(1)}%`
    );
  }
  console.log(`${"TOTAL".padEnd(16)} ${String(totalAll).padStart(7)}  ${String(emptyAll).padStart(14)}   ${((emptyAll / totalAll) * 100).toFixed(1)}%`);

  // Also: of the NON-empty descriptions, how short are they on average per
  // source (to gauge whether even "present" descriptions are thin one-liners).
  const sample = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true, NOT: [{ description: null }, { description: "" }] },
    select: { source: true, description: true },
  });
  const lenBySource = new Map<string, number[]>();
  for (const r of sample) {
    const arr = lenBySource.get(r.source) ?? [];
    arr.push((r.description ?? "").length);
    lenBySource.set(r.source, arr);
  }
  console.log("\nsource            avg desc length (chars, non-empty only)");
  for (const [source, lens] of lenBySource) {
    const avg = lens.reduce((a, b) => a + b, 0) / lens.length;
    console.log(`${source.padEnd(16)} ${avg.toFixed(0)}`);
  }

  await db.$disconnect();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

