import { db } from "../lib/db";

async function main() {
  const rows = await db.gameMod.findMany({
    where: { source: "github" },
    select: { name: true, slug: true, gameFamily: true, iconUrl: true, galleryUrls: true, description: true },
    take: 30,
  });
  for (const r of rows) {
    console.log(JSON.stringify(r));
  }
  await db.$disconnect();
}
