input.content:
/**
 * Backfill `GameMod.longDescription` for existing Modrinth rows — the real
 * quick win identified investigating NxLabs's thin-description complaint
 * (2026-09-20 owner screenshot review: CounterStrikeSharp's description was
 * just GitHub's one-line repo `description`, "C# plugin runtime most CS2
 * plugins need.").
 *
 * PER-SOURCE INVESTIGATION (what this script does and does not fix):
 *
 *   - Modrinth: a real DB check (scripts/_tmp-check-descriptions.ts, run
 *     2026-09-20, then deleted) found 0 null/empty descriptions catalogue-wide
 *     but every source's `description` is a short one-liner (avg 42-84
 *     chars) — that field is Modrinth's own search-hit `description` (a
 *     tagline), never its `body` field (the project's actual page content —
 *     confirmed live: `GET /v2/project/sodium` returns a `body` of 5,594
 *     characters of real markdown, completely separate from its 124-char
 *     `description`). scripts/import-modrinth-catalog.ts's own `FullProject`
 *     type (used for its bulk `/v2/projects?ids=[...]` call) simply never
 *     read `body` off the response it already had in hand. THIS script fixes
 *     that gap for existing rows without touching the import script itself
 *     (per this task's "concurrent import pipeline work in progress"
 *     constraint) — it makes the SAME bulk `/v2/projects?ids=[...]` call
 *     (which also carries `body`, confirmed live) over already-imported
 *     modrinth rows and writes the real result into the new
 *     `longDescription` column. Nothing is fabricated: a project whose body
 *     is empty gets left null, not padded.
 *
 *   - GitHub: NOT touched by this script. A repo's `description` field IS
 *     the whole of what GitHub's repo metadata offers for a one-liner — there
 *     is no hidden longer field the way Modrinth has `body`. The closest real
 *     "richer, already-public" text is a repo's README
 *     (`GET /repos/{o}/{r}/readme`), which is a genuinely different fetch
 *     (a different API, different rate limit, needs its own markdown-vs-HTML
 *     handling) layered on top of the GitHub import pipeline another agent is
 *     actively building right now (scripts/import-github-catalog.ts) — adding
 *     it here would mean editing that in-progress file. Left as a note for
 *     whoever owns that pipeline next, not implemented in this pass.
 *
 *   - Thunderstore / uMod / SpigotMC / Nexus / Codefling: not investigated in
 *     this pass (12 rows total across all four, sourceId formats and APIs
 *     all differ) — Modrinth alone is 32,243 of the catalogue's 32,331 active
 *     rows (99.7%), so it is where a backfill actually moves the needle.
 *
 * IDEMPOTENT: only touches rows where `longDescription IS NULL` by default
 * (safe to re-run — it converges rather than re-fetching the same rows
 * forever); pass --refresh to also re-fetch rows that already have one (e.g.
 * after a project has updated its page).
 *
 * SAFETY: this is a bulk-WRITE script, so it goes through the same
 * NXEON_DB_TARGET confirmation as every other writing script in this repo
 * (scripts/db-target-guard.ts) and defaults to a dry run.
 *
 *   Dry run (no writes), tiny slice:
 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/backfill-modrinth-descriptions.ts --limit=50
 *
 *   Real write, tiny slice:
 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/backfill-modrinth-descriptions.ts --limit=50 --apply
 *
 *   Full real run:
 *     NXEON_DB_TARGET=nxeon npx tsx scripts/backfill-modrinth-descriptions.ts --apply
 */

import { assertDbTarget } from "./db-target-guard";
assertDbTarget("backfill-modrinth-descriptions.ts");

import { db } from "../lib/db";

const UA = "Nxeon/1.0 (mods@nxeon.cloud)";
const MODRINTH_KEY = process.env.MODRINTH_API_KEY ?? "";
const API = "https://api.modrinth.com/v2";
const BATCH_SIZE = 100; // Modrinth's real cap on /projects?ids=[...]
const RATE_LIMIT_PER_MIN = 280; // stay under Modrinth's real 300/min, matches import-modrinth-catalog.ts

function parseArgs(argv: string[]) {
  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
  return {
    apply: argv.includes("--apply"),
    refresh: argv.includes("--refresh"),
    limit: get("limit") ? Number(get("limit")) : undefined,
  };
}

class RateLimiter {
  private minIntervalMs: number;
  private last = 0;
  constructor(perMin: number) {
    this.minIntervalMs = 60_000 / perMin;
  }
  async wait() {
    const elapsed = Date.now() - this.last;
    if (elapsed < this.minIntervalMs) await new Promise((r) => setTimeout(r, this.minIntervalMs - elapsed));
    this.last = Date.now();
  }
}

async function apiFetch(limiter: RateLimiter, url: string, attempt = 1): Promise<Response> {
  await limiter.wait();
  const headers: Record<string, string> = { "User-Agent": UA };
  if (MODRINTH_KEY) headers.Authorization = MODRINTH_KEY;
  const res = await fetch(url, { headers });
  if (res.status === 429 && attempt <= 6) {
    const retryAfterMs = Number(res.headers.get("retry-after") ?? 0) * 1000;
    const backoffMs = Math.max(retryAfterMs, 1000 * 2 ** attempt);
    console.warn(`  [rate-limit] 429 — backing off ${Math.round(backoffMs / 1000)}s (attempt ${attempt})`);
    await new Promise((r) => setTimeout(r, backoffMs));
    return apiFetch(limiter, url, attempt + 1);
  }
  if (res.status >= 500 && attempt <= 4) {
    const backoffMs = 1000 * 2 ** attempt;
    console.warn(`  [server-error] ${res.status} — retrying in ${Math.round(backoffMs / 1000)}s`);
    await new Promise((r) => setTimeout(r, backoffMs));
    return apiFetch(limiter, url, attempt + 1);
  }
  return res;
}

type FullProject = { id: string; slug: string; body?: string | null };

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const limiter = new RateLimiter(RATE_LIMIT_PER_MIN);

  const rows = await db.gameMod.findMany({
    where: {
      source: "modrinth",
      sourceId: { not: null },
      ...(args.refresh ? {} : { longDescription: null }),
    },
    select: { id: true, sourceId: true, name: true },
    ...(args.limit ? { take: args.limit } : {}),
  });

  console.log(
    `[backfill-modrinth-descriptions] ${rows.length} row(s) to check` +
      (args.refresh ? " (--refresh: including rows that already have one)" : " (rows with longDescription IS NULL)") +
      (args.apply ? " — APPLY mode" : " — DRY RUN, no writes")
  );
  if (rows.length === 0) {
    await db.$disconnect();
    return;
  }

  const bySlug = new Map(rows.map((r) => [r.sourceId!, r]));
  const slugs = [...bySlug.keys()];

  let checked = 0;
  let filled = 0;
  let emptyBody = 0;
  let missingFromApi = 0;
  let failed = 0;

  for (let i = 0; i < slugs.length; i += BATCH_SIZE) {
    const batch = slugs.slice(i, i + BATCH_SIZE);
    const idsParam = encodeURIComponent(JSON.stringify(batch));
    const res = await apiFetch(limiter, `${API}/projects?ids=${idsParam}`);
    if (!res.ok) {
      console.error(`  [batch ${i / BATCH_SIZE + 1}] HTTP ${res.status} — skipping this batch of ${batch.length}`);
      failed += batch.length;
      continue;
    }
    const projects: FullProject[] = await res.json();
    // Modrinth's bulk endpoint accepts either real ids or slugs and echoes
    // back whichever the project's canonical `slug` is today, which does not
    // always match what we stored (renames happen) — index by BOTH id and
    // slug from the response, then fall back to matching in requested order
    // for any that still don't line up.
    const byIdOrSlug = new Map<string, FullProject>();
    for (const p of projects) {
      byIdOrSlug.set(p.id, p);
      byIdOrSlug.set(p.slug, p);
    }

    for (const requestedSlug of batch) {
      checked++;
      const row = bySlug.get(requestedSlug)!;
      const proj = byIdOrSlug.get(requestedSlug);
      if (!proj) {
        missingFromApi++;
        continue;
      }
      const body = (proj.body ?? "").trim();
      if (!body) {
        emptyBody++;
        continue;
      }
      filled++;
      if (args.apply) {
        try {
          await db.gameMod.update({ where: { id: row.id }, data: { longDescription: body } });
        } catch (e) {
          failed++;
          filled--;
          const msg = e instanceof Error ? e.message : String(e);
          console.error(`  [db] failed to update ${row.name} (${requestedSlug}): ${msg}`);
        }
      }
    }

    console.log(
      `  [batch ${Math.floor(i / BATCH_SIZE) + 1}/${Math.ceil(slugs.length / BATCH_SIZE)}] ` +
        `checked=${checked} filled=${filled} empty_body=${emptyBody} missing=${missingFromApi} failed=${failed}`
    );
  }

  console.log(
    `\n[backfill-modrinth-descriptions] done. checked=${checked} ${args.apply ? "filled" : "would_fill"}=${filled} ` +
      `empty_body=${emptyBody} missing_from_api=${missingFromApi} failed=${failed}`
  );
  if (!args.apply) console.log("Dry run only — re-run with --apply to write.");

  await db.$disconnect();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

