189	/**
190	 * Every scalar `orderBy` StoreBrowser's sort tabs can ask for. "rating" is
191	 * the one honest exception: avgRating is computed from a separate ModRating
192	 * table with no cached column on GameMod, and Prisma's relation-aggregate
193	 * `orderBy` only supports `_count` (not `_avg`) for to-many relations — there
194	 * is no cheap DB-side "top rated" ordering to give it. Fetching by downloads
195	 * and re-sorting by rating WITHIN each page (below) is a documented
196	 * approximation: "Top Rated" page 2 shows the 25th-48th most-downloaded mods
197	 * re-ordered by rating, not the true 25th-48th highest-rated mods
198	 * catalogue-wide. That is honest and fine at today's rating volumes (a small
199	 * fraction of 32k+ mods have any reviews at all); if ratings ever justify
200	 * it, add a cached avgRating/ratingCount column on GameMod (maintained by
201	 * the rating mutation) and give this its own real orderBy.
202	 */
203	const ORDER_BY: Record<CatalogSort, Prisma.GameModOrderByWithRelationInput[]> = {
204	  featured: [{ featured: "desc" }, { downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
205	  downloads: [{ downloads: "desc" }, { name: "asc" }],
206	  latest: [{ createdAt: "desc" }],
207	  rating: [{ downloads: "desc" }, { name: "asc" }],
208	};
