210	/**
211	 * Real, server-side, paginated + searched + sorted catalogue query — the
212	 * single data source behind every StoreBrowser instance (marketing and
213	 * portal, cross-game and per-family). Replaces the old
214	 * `listCatalogMods`/`searchCatalogMods` pair, which fetched (at most)
215	 * `CATALOG_LIST_CAP` rows once and left every control on top of it running
216	 * over that fixed in-memory array — fine at ~124 hand-seeded rows, silently
217	 * capping the catalogue at families with thousands+ of real imported rows.
218	 */
219	export async function queryCatalogMods(opts: {
220	  family?: string;
221	  /** Category filter — the per-family page's chips (StoreBrowser's `chipField: "category"`). */
222	  category?: string;
223	  q?: string;
224	  sort?: CatalogSort;
225	  page?: number;
226	  perPage?: number;
227	}): Promise<CatalogPage> {
228	  const sort = opts.sort ?? "featured";
229	  const q = (opts.q ?? "").trim();
230	  const where: Prisma.GameModWhereInput = {
231	    active: true,
232	    upstreamOk: true,
233	    ...(opts.family ? { gameFamily: opts.family } : {}),
234	    ...(opts.category ? { category: opts.category } : {}),
235	    ...(q
236	      ? {
237	          OR: [
238	            { name: { contains: q, mode: "insensitive" } },
239	            { category: { contains: q, mode: "insensitive" } },
240	            { description: { contains: q, mode: "insensitive" } },
241	          ],
242	        }
243	      : {}),
244	  };
245	
246	  const total = await db.gameMod.count({ where });
247	  const { skip, take, page, pages, perPage } = paginate(
248	    { page: opts.page != null ? String(opts.page) : undefined },
249	    total,
250	    opts.perPage ?? CATALOG_PAGE_SIZE
251	  );
252	
253	  const rows = await db.gameMod.findMany({ where, orderBy: ORDER_BY[sort], skip, take });
254	  const aggs = await ratingAggs(rows.map((r) => r.id));
255	  const mods = rows.map((r) => toSummary(r, aggs.get(r.id)));
256	  if (sort === "rating") {
257	    mods.sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount);
258	  }
259	
260	  return { mods, total, page, totalPages: pages, perPage };
261	}
