import Link from "next/link";
import { notFound } from "next/navigation";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageShell } from "@/components/nx/PageShell";
import { ModCard } from "@/components/mods/ModCard";
import { AddToServerWidget } from "@/components/mods/AddToServerWidget";
import { AuthorBadge } from "@/components/mods/AuthorBadge";
import { GalleryStrip } from "@/components/mods/GalleryStrip";
import { RatingsAndComments } from "@/components/mods/RatingsAndComments";
import { GAME_ART_SLUG, type GameFamily } from "@/lib/games";
import { renderMarkdown } from "@/lib/blog";
import {
  getCatalogMod,
  relatedCatalogMods,
  recommendedPlanFor,
  resolveDownloadUrl,
  listModComments,
  getMyModRating,
  formatDownloads,
  formatBytes,
  SOURCE_LABEL,
} from "@/lib/mods-catalog";

export const dynamic = "force-dynamic";

/**
 * Portal's own mod-detail route — genuinely separate from the public
 * /mods/[family]/[slug] page (item 1 of the NxLabs brief). Same underlying
 * data (lib/mods-catalog.ts), rendered through the Nexion portal shell by
 * virtue of living under app/dashboard/**, with its own breadcrumbs back
 * into /dashboard/nxlabs instead of the public catalog.
 */
export default async function PortalModDetailPage({ params }: { params: Promise<{ family: string; slug: string }> }) {
  const { family, slug } = await params;
  const user = await requireUser();
  const mod = await getCatalogMod(family, slug);
  if (!mod) notFound();

  const [gamePlans, related, download, commentsPage, myRating] = await Promise.all([
    db.gamePlan.findMany({ where: { gameFamily: mod.gameFamily, active: true }, orderBy: { priceCents: "asc" } }),
    relatedCatalogMods(mod, 4),
    resolveDownloadUrl(mod),
    listModComments(mod.id, { take: 10 }),
    getMyModRating(mod.id, user.id),
  ]);
  const recommended = recommendedPlanFor(mod, gamePlans);
  const downloads = formatDownloads(mod.downloads);
  const fileSize = formatBytes(mod.fileBytes);
  // Same fallback the public detail page uses (item 2 of the NxLabs brief):
  // most catalogue rows (every github-sourced mod included) have neither a
  // gallery screenshot nor an icon, and this page used to render nothing
  // visual at all for them. Falls back to the family's own hero art
  // (GAME_ART_SLUG, same source the per-family browse page already uses) so
  // the header always has real game context, contained inside a normal
  // rounded panel here rather than the marketing page's full-bleed section —
  // the dashboard shell has a fixed content width against the sidebar, no
  // room for a viewport-edge bleed.
  const familyHeroSlug = GAME_ART_SLUG[mod.gameFamily as GameFamily]?.hero;
  const ownHeroImage = mod.galleryUrls[0] ?? mod.iconUrl ?? null;
  const heroImage = ownHeroImage ?? (familyHeroSlug ? `/games/art/${familyHeroSlug}_hero.jpg` : null);
  const heroIsGameArt = !ownHeroImage && !!heroImage;
  const longDescriptionHtml = mod.longDescription ? renderMarkdown(mod.longDescription.slice(0, 6000)) : null;

  return (
    <PageShell eyebrow="NxLabs" title={mod.name} sub={mod.description ?? undefined} tagline={["VERIFIED SOURCES.", "ONE-CLICK INSTALL."]}>
      <p className="-mt-2 mb-4 text-xs text-tx-mute">
        <Link href="/dashboard/nxlabs" className="hover:underline">
          NxLabs
        </Link>{" "}
        /{" "}
        <Link href={`/dashboard/nxlabs/games/${mod.gameFamily}`} className="hover:underline">
          {mod.gameFamilyLabel}
        </Link>
      </p>

      <div className="grid gap-8 lg:grid-cols-[1.4fr_1fr]">
        <div className="space-y-6">
          <div className="relative mb-2 min-h-[140px] overflow-hidden rounded-2xl border border-white/10">
            {heroImage && (
              <>
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img
                  src={heroImage}
                  alt=""
                  aria-hidden
                  className={`absolute inset-0 h-full w-full object-cover ${heroIsGameArt ? "opacity-40" : "opacity-30 blur-sm"}`}
                />
                <div className="absolute inset-0 bg-gradient-to-t from-navy-950 via-navy-950/75 to-navy-950/30" />
              </>
            )}
            <div className="relative flex flex-wrap items-center gap-4 p-6">
              {mod.iconUrl ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img src={mod.iconUrl} alt="" className="h-16 w-16 rounded-2xl border border-white/10 object-cover" />
              ) : (
                <div className="flex h-16 w-16 shrink-0 items-center justify-center rounded-2xl border border-white/10 bg-white/[0.06] text-2xl font-bold text-tx-mute">
                  {mod.name.slice(0, 1)}
                </div>
              )}
              {mod.authorName && <AuthorBadge name={mod.authorName} avatarUrl={mod.authorAvatarUrl} />}
            </div>
          </div>

          {mod.galleryUrls.length > 0 && <GalleryStrip images={mod.galleryUrls} alt={mod.name} />}

          {longDescriptionHtml && (
            <div className="card p-6">
              <h2 className="text-lg font-semibold text-white">Description</h2>
              {/* Same sanitizing renderer as the marketing detail page — see
                  its identical comment for why this is safe against
                  third-party markdown (lib/blog.ts's renderMarkdown escapes
                  text before any tag is produced). */}
              <div
                className="mt-3 text-sm text-tx-mute"
                // eslint-disable-next-line react/no-danger
                dangerouslySetInnerHTML={{ __html: longDescriptionHtml }}
              />
            </div>
          )}

          <div className="card p-6">
            <h2 className="text-lg font-semibold text-white">Download</h2>
            {download ? (
              <>
                <a href={download.url} className="btn-primary mt-4 inline-flex" target="_blank" rel="noopener noreferrer nofollow">
                  {download.direct ? "Download file" : `View on ${SOURCE_LABEL[mod.source] ?? mod.source}`}
                </a>
              </>
            ) : (
              <p className="mt-3 text-sm text-tx-mute">No download link is available for this entry right now.</p>
            )}
            <div className="mt-6">
              <AddToServerWidget modId={mod.id} gameFamily={mod.gameFamilyLabel} downloadUrl={download?.url ?? null} />
            </div>
            {!mod.upstreamOk && (
              <p className="mt-4 rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
                {mod.upstreamNote || "This mod is no longer supported by its source."}
              </p>
            )}
          </div>

          <RatingsAndComments
            modId={mod.id}
            avgRating={mod.avgRating}
            ratingCount={mod.ratingCount}
            initialComments={commentsPage.comments}
            initialCursor={commentsPage.nextCursor}
            myRating={myRating}
            isLoggedIn
            isAdmin={user.role === "ADMIN"}
            loginHref="/login"
          />
        </div>

        <aside className="space-y-6">
          <div className="card p-6">
            <h2 className="text-sm font-semibold uppercase tracking-wide text-tx-mute">Details</h2>
            <dl className="mt-4 space-y-3 text-sm">
              <Row label="Game">{mod.gameFamilyLabel}</Row>
              <Row label="Category">{mod.category}</Row>
              <Row label="Source">{SOURCE_LABEL[mod.source] ?? mod.source}</Row>
              {mod.license && <Row label="License">{mod.license}</Row>}
              {downloads && <Row label="Downloads">{downloads}</Row>}
              {fileSize && <Row label="File size">{fileSize}</Row>}
              {mod.gameVersions.length > 0 && <Row label="Game versions">{mod.gameVersions.slice(-6).reverse().join(", ")}</Row>}
              {mod.loaders.length > 0 && <Row label="Loaders">{mod.loaders.join(", ")}</Row>}
              {mod.appliesToVariant && <Row label="Requires">{mod.appliesToVariant} server type</Row>}
              {mod.serverSide && <Row label="Server support">{mod.serverSide}</Row>}
              <Row label="Verified">{mod.verified ? `Yes — checked ${mod.verifiedAt?.toISOString().slice(0, 10)}` : "Not yet verified"}</Row>
            </dl>
          </div>

          <div className="card p-6">
            <h2 className="text-sm font-semibold uppercase tracking-wide text-tx-mute">Recommended server</h2>
            {recommended ? (
              <p className="mt-3 text-sm text-tx-mute">
                Works well on <span className="text-white">{recommended.planName}</span> (
                {(recommended.ramMB / 1024).toFixed(recommended.ramMB % 1024 ? 1 : 0)} GB RAM) or higher —{" "}
                <Link href="/dashboard/deploy" className="text-brand-300 underline underline-offset-2">
                  deploy one
                </Link>
                .
              </p>
            ) : (
              <p className="mt-3 text-sm text-tx-mute">
                {mod.impactNote || "This is a light install and should run fine on any active plan for this game."}
              </p>
            )}
          </div>
        </aside>
      </div>

      {related.length > 0 && (
        <div className="mt-12">
          <h2 className="text-lg font-semibold text-white">More for {mod.gameFamilyLabel}</h2>
          <div className="mt-4 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {related.map((r) => (
              <ModCard key={r.id} mod={r} href={`/dashboard/nxlabs/${r.gameFamily}/${r.slug}`} />
            ))}
          </div>
        </div>
      )}
    </PageShell>
  );
}

function Row({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex items-start justify-between gap-4">
      <dt className="text-tx-mute">{label}</dt>
      <dd className="text-right text-white">{children}</dd>
    </div>
  );
}

