import type { Metadata } from "next";
import Link from "next/link";
import { Eyebrow, Section, SectionTitle } from "@/components/marketing/primitives";
import { GameParticleField } from "@/components/marketing/showcase/GameParticleField";
import { StoreBrowser, type SortKey } from "@/components/mods/StoreBrowser";
import { PopularGamesStrip } from "@/components/mods/PopularGamesStrip";
import { FaqJsonLd } from "@/components/marketing/StructuredData";
import { listCatalogFamilies, queryCatalogMods, totalDownloadsFor, formatDownloads } from "@/lib/mods-catalog";

export const dynamic = "force-dynamic";

const VALID_SORTS = new Set<SortKey>(["featured", "downloads", "latest", "rating"]);
function parseSort(v?: string): SortKey {
  return v && VALID_SORTS.has(v as SortKey) ? (v as SortKey) : "featured";
}

export const metadata: Metadata = {
  title: "NxLabs — Free Mods, Plugins & Server Add-ons",
  description:
    "NxLabs is Nxeon's free, public mod & plugin catalog — verified against Modrinth, SpigotMC, and Thunderstore. Browse and download with no account required.",
  alternates: { canonical: "/mods" },
  openGraph: { title: "NxLabs — Free Mods, Plugins & Server Add-ons", type: "website" },
};

const FAQ = [
  {
    q: "Do I need an Nxeon account to download from NxLabs?",
    a: "No. Every mod page links to its real, authoritative source (Modrinth, SpigotMC, or Thunderstore) — anyone can download for free with no account.",
  },
  {
    q: "What does \"Verified\" mean on a mod?",
    a: "Verified mods have been checked live against their source's own API — real download counts, supported game versions, and file size, refreshed periodically so a removed or deprecated project stops being listed.",
  },
  {
    q: "Can I install a mod straight onto my server?",
    a: "If you have an Nxeon game server matching the mod's game, log in and use \"Add to my server\" for a one-click install. Anyone else gets the same direct download link.",
  },
];

type Search = { q?: string; sort?: string; page?: string };

export default async function ModsCatalogPage({ searchParams }: { searchParams: Promise<Search> }) {
  const sp = await searchParams;
  const q = (sp.q ?? "").trim();
  const sort = parseSort(sp.sort);
  const page = Number(sp.page) || 1;

  const [families, result, totalDownloads] = await Promise.all([
    listCatalogFamilies(),
    queryCatalogMods({ q, sort, page }),
    totalDownloadsFor(),
  ]);
  const { mods, total, totalPages, perPage, page: resolvedPage } = result;
  const totalMods = families.reduce((sum, f) => sum + f.count, 0);

  // Family chips point at the real dedicated /mods/games/[family] pages
  // (already correctly paginated) rather than re-filtering this page's own
  // array in place — the counts here are real DB-wide totals
  // (listCatalogFamilies' own groupBy), and at 32k+ mods in one family a
  // client-side re-filter of just this page's ~24 loaded rows could show
  // "0 results" for a chip advertising thousands.
  const chips = families.map((f) => ({ key: f.family, label: f.label, count: f.count, href: `/mods/games/${f.family}` }));

  return (
    <>
      <FaqJsonLd items={FAQ} />

      {/* Full-bleed hero — matches the approved mockup
          (.design-refs/nxlabs/marketing-home.png): the collage stretches
          edge-to-edge as a backdrop the copy sits directly on top of, not the
          boxed/inset "text left, art right" treatment <PageHero>'s `visual`
          slot gives every other sub-page (see primitives.tsx — that slot is
          the right call for an infra product explained in prose; it isn't for
          the one page selling a visual, mod-rich catalog). Bespoke markup
          rather than a new PageHero variant, since no other sub-page needs
          this treatment today.

          Image + gradient + copy are all plain server-rendered markup — no
          <Reveal>, no client-JS gate. This exact page had a real bug earlier
          today where a scroll-reveal wrapper made the hero invisible above
          the fold; the particle canvas below is strictly additive on top of
          an already-complete, already-visible hero, never a prerequisite for
          seeing it. */}
      <section className="relative flex min-h-[480px] items-center overflow-hidden sm:min-h-[560px] lg:min-h-[600px]">
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src="/nxlabs/hero-collage.png"
          alt=""
          aria-hidden
          className="absolute inset-0 -z-20 h-full w-full object-cover object-center"
        />
        {/* Left-to-right dark fade so the title/CTAs stay legible over the art
            (mirrors the mockup's left-copy/right-art balance), plus a bottom
            fade so the hero blends into the page instead of ending on a hard
            edge. Real var(--color-bg) (defined in globals.css) via the same
            color-mix idiom the dashboard's own aurora backgrounds already use
            (components/nx/PlateBg.tsx etc.) — NOT the undefined `--bg` a
            couple of sibling NxLabs hero overlays reference (see this
            change's fix in mods/[family]/[slug]/page.tsx). */}
        <div
          aria-hidden
          className="pointer-events-none absolute inset-0 -z-10"
          style={{
            background:
              "linear-gradient(90deg, var(--color-bg) 0%, color-mix(in srgb, var(--color-bg) 82%, transparent) 34%, color-mix(in srgb, var(--color-bg) 30%, transparent) 62%, transparent 100%), " +
              "linear-gradient(to top, var(--color-bg) 0%, transparent 32%)",
          }}
        />
        {/* Ambient ember field — reuses the same canvas already shipped for
            the /game-servers hero carousel (GameParticleField), tinted to
            Nxeon's own brand gradient (blue -> violet). A constant
            `triggerKey` means the "burst on change" half of that component
            never fires here; only its slow ambient drift renders — "maybe
            some particle effect" from the owner's review, kept tasteful and
            reused rather than a new one-off effect. Respects
            prefers-reduced-motion internally (no particles seeded at all, see
            GameParticleField's own header comment). Purely decorative
            (pointer-events-none) and layered under the copy, so it can never
            block the hero from being read or clicked. */}
        <GameParticleField colorFrom="#3b6be8" colorTo="#7b3fef" triggerKey="mods-hero" />

        <div className="rail relative w-full py-16 sm:py-20">
          <div className="max-w-xl">
            <div className="mb-5 flex">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src="/nxlabs/logo.png" alt="NxLabs" className="h-10 w-auto" />
            </div>
            <Eyebrow pill>Mods fuel better games</Eyebrow>
            <h1 className="mt-5 text-4xl font-bold leading-[1.08] tracking-tight text-white sm:text-5xl lg:text-6xl text-balance">
              Customize without <span className="grad-text">limits</span>
            </h1>
            <p className="mt-6 max-w-xl text-lg leading-relaxed text-slate-400 sm:text-xl">
              Discover, download, and share verified mods, plugins, and add-ons for your favorite Nxeon-hosted games —
              real download counts, real licenses, always a direct link to the source.
            </p>
            <div className="mt-9 flex flex-wrap gap-3">
              <Link href="#browse" className="btn-deploy px-5 py-3 text-base">
                Browse mods
                <span className="dep-arrow" aria-hidden>
                  →
                </span>
              </Link>
              <Link href="#games" className="btn-secondary px-5 py-3 text-base">
                Explore games
              </Link>
            </div>
            <div className="mt-10 grid max-w-md grid-cols-3 gap-6">
              <HeroStat value={totalMods.toLocaleString()} label="Mods & plugins" />
              <HeroStat value={String(families.length)} label="Games supported" />
              <HeroStat value={formatDownloads(totalDownloads) ?? "0"} label="Total downloads" />
            </div>
          </div>
        </div>
      </section>

      <Section>
        <div id="games">
          <SectionTitle eyebrow="Browse by game" title="Popular games" />
          <div className="mt-6">
            <PopularGamesStrip families={families} hrefFor={(family) => `/mods/games/${family}`} />
          </div>
        </div>
      </Section>

      <Section>
        <div id="browse">
          <SectionTitle eyebrow="The full catalog" title="Featured mods" />
          <div className="mt-6">
            <StoreBrowser
              mods={mods}
              total={total}
              page={resolvedPage}
              totalPages={totalPages}
              perPage={perPage}
              chips={chips}
              chipField="gameFamily"
              basePath="/mods"
              q={q}
              sort={sort}
              showGameBadge
            />
          </div>
        </div>
      </Section>

      <Section>
        <SectionTitle title="Frequently asked" />
        <div className="mx-auto mt-6 max-w-2xl divide-y divide-white/10">
          {FAQ.map((f) => (
            <div key={f.q} className="py-4">
              <h3 className="text-sm font-semibold text-[var(--fg)]">{f.q}</h3>
              <p className="mt-1 text-sm text-[var(--fg-muted)]">{f.a}</p>
            </div>
          ))}
        </div>
        <p className="mt-8 text-center text-xs text-[var(--fg-muted)]">
          Running an Nxeon game server? Install any of these in one click from your{" "}
          <Link href="/dashboard/nxlabs" className="text-brand-300 underline underline-offset-2">
            dashboard
          </Link>
          , or read about our built-in{" "}
          <Link href="/game-servers/mods" className="text-brand-300 underline underline-offset-2">
            Mod Store
          </Link>
          .
        </p>
      </Section>
    </>
  );
}

/** Hero-only stat tile — hardcoded white/slate text (like <PageHero>'s own
 *  copy) rather than the `--fg`/`--fg-muted` theme vars the page's other
 *  sections use below: this sits on a dark image+gradient backdrop
 *  regardless of the site's light/dark theme toggle, same as GameHero. */
function HeroStat({ value, label }: { value: string; label: string }) {
  return (
    <div>
      <p className="text-2xl font-bold text-white sm:text-3xl">{value}</p>
      <p className="text-xs text-slate-400 sm:text-sm">{label}</p>
    </div>
  );
}

