import { chromium } from "playwright";
import { mkdirSync } from "fs";

const base = process.argv[2]; // e.g. http://127.0.0.1 or http://127.0.0.1:8080
const outDir = process.argv[3]; // e.g. /root/nxlabs-shots/before
mkdirSync(outDir, { recursive: true });

const pages = [
  { path: "/mods", name: "mods-home.png", waitFor: 800 },
  { path: "/mods/cs2/counterstrikesharp", name: "mod-detail-cs2-css.png", waitFor: 800 },
];

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
for (const p of pages) {
  const page = await ctx.newPage();
  const url = base + p.path;
  console.log("navigating", url);
  const resp = await page.goto(url, { waitUntil: "networkidle", timeout: 30000 }).catch((e) => {
    console.error("nav error", p.path, e.message);
    return null;
  });
  console.log(p.path, "status:", resp?.status());
  await page.waitForTimeout(p.waitFor);
  await page.screenshot({ path: `${outDir}/${p.name}`, fullPage: false });
  await page.close();
}
await browser.close();
console.log("done ->", outDir);

import { chromium } from "playwright";
import { mkdirSync } from "fs";

const base = process.argv[2]; // e.g. http://127.0.0.1 or http://127.0.0.1:8080
const outDir = process.argv[3]; // e.g. /root/nxlabs-shots/before
const host = process.argv[4]; // Host header to send, e.g. nxeon.cloud
mkdirSync(outDir, { recursive: true });

const pages = [
  { path: "/mods", name: "mods-home.png", waitFor: 1000 },
  { path: "/mods/cs2/counterstrikesharp", name: "mod-detail-cs2-css.png", waitFor: 1000 },
];

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, extraHTTPHeaders: host ? { Host: host } : {} });
ctx.on("requestfailed", (r) => console.log("  [failed]", r.url(), r.failure()?.errorText));
for (const p of pages) {
  const page = await ctx.newPage();
  page.on("response", (r) => {
    if (r.url().includes(".css") || r.status() >= 400) console.log("  [resp]", r.status(), r.url());
  });
  const url = base + p.path;
  console.log("navigating", url);
  const resp = await page.goto(url, { waitUntil: "networkidle", timeout: 30000 }).catch((e) => {
    console.error("nav error", p.path, e.message);
    return null;
  });
  console.log(p.path, "status:", resp?.status());
  await page.waitForTimeout(p.waitFor);
  await page.screenshot({ path: `${outDir}/${p.name}`, fullPage: false });
  await page.close();
}
await browser.close();
console.log("done ->", outDir);

