// Runs once when the Next.js server process starts (both web instances).
// Validates critical env vars and logs a clear warning if any are missing.
export async function register() {
  try {
    const { validateEnv } = await import("@/lib/env");
    const result = validateEnv();
    if (!result.ok) {
      console.warn(`[nxeon] Missing/invalid env vars: ${result.missing.join(", ")}`);
